    },
    history: {
      type: "string" as const,
      description: "Historical/pre-Linnaean context (Markdown supported)",
    },
    distribution: {
      type: "string" as const,
      description: "Geographic range (Markdown supported)",
    },
  },
  required: [
    "scientificName",
    "author",
    "commonName",
    "family",
    "quickRecap",
    "diagnosticDescription",
    "confusedTaxa",
    "ecology",
    "etymology",
    "history",
    "distribution",
  ],
};

// Helper to extract sources from grounding metadata
const extractSources = (response: any): Source[] => {
  const sources: Source[] = [];
  const candidates = response.candidates;
  if (candidates && candidates.length > 0) {
    const candidate = candidates[0];
    const groundingMetadata = candidate.groundingMetadata;
    if (groundingMetadata && groundingMetadata.groundingChunks) {
      groundingMetadata.groundingChunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({
            title: chunk.web.title || "Source",
            uri: chunk.web.uri,
          });
        }
      });
    }
  }
  // Deduplicate sources by URI
  return Array.from(new Map(sources.map((s) => [s.uri, s])).values());
};

const handleApiError = (error: any) => {
  console.error("Gemini API Error:", error);
  const msg = error.message || "";
  const name = error.name || "";

  // Specific handling for AbortError which often happens in Firefox with AdBlockers or strict privacy settings on long requests
  if (
    name === "AbortError" ||
    msg.includes("aborted") ||
    msg.includes("Failed to fetch")
  ) {
    throw new Error(
      "Connection failed or was aborted. If you are using Firefox, this is a known issue caused by strict tracking protection or extensions—please try using Chrome or disabling ad-blockers for this site."
    );
  }
  throw error;
};

export const analyzeTaxon = async (taxonName: string): Promise<TaxonData> => {
  try {
    const ai = new GoogleGenAI({ apiKey: getApiKey() });

    const prompt = `Act as an expert Taxonomist and Field Biologist.
Analyze the taxon: "${taxonName}".

First, use Google Search to verify the latest taxonomic classifications and precise diagnostic morphological characters from authoritative databases (e.g., GBIF, IPNI, Index Fungorum).

Provide a strictly factual, professional profile.
If the taxon name is ambiguous, select the most likely valid scientific species.
Ensure the author citation is absolutely accurate.

IMPORTANT: For all text fields, use standard Markdown formatting. 
For 'diagnosticDescription', provide a clean Markdown bulleted list of features. Do not use conversational filler.`;

    const response = await ai.models.generateContent({
