import { GoogleGenAI } from "@google/genai";
import { TaxonData, ComparisonData, Source } from "../types";

// Helper to get the API Key securely
const getApiKey = (): string => {
  const key = process.env.API_KEY;
  if (!key) {
    throw new Error("API_KEY is not defined in the environment variables.");
  }
  return key;
};

// Define the response schemas using Gemini's schema format
const confusedTaxonSchema = {
  type: "object" as const,
  properties: {
    name: {
      type: "string" as const,
      description: "Name of confused taxon",
    },
    difference: {
      type: "string" as const,
      description: "How to distinguish it (Markdown supported, use bolding for keywords)",
    },
    keyFeature: {
      type: "string" as const,
      description: "Specific feature to look at",
    },
  },
  required: ["name", "difference", "keyFeature"],
};

const taxonSchema = {
  type: "object" as const,
  properties: {
    scientificName: {
      type: "string" as const,
      description: "Formal scientific name",
    },
    author: {
      type: "string" as const,
      description: "Standard botanical or zoological author citation (e.g. 'L.', 'Linnaeus', '(Lam.) J.St.-Hil.')",
    },
    commonName: {
      type: "string" as const,
      description: "Most common vernacular name",
    },
    family: {
      type: "string" as const,
      description: "Biological family",
    },
    quickRecap: {
      type: "string" as const,
      description: "A 2-3 sentence summary. This MUST include at least two absolute primary diagnostic morphological characters. Use bolding for the most decisive characters.",
    },
    diagnosticDescription: {
      type: "string" as const,
      description: "Comprehensive morphological identification guide using a structured Markdown list. Each feature (e.g., Habit, Leaves, Flowers) MUST be its own list item starting with a bolded header and colon. Use bolding (e.g., **pinnate**, **glabrous**) for decisive anatomical terms.",
    },
    confusedTaxa: {
      type: "array" as const,
      items: confusedTaxonSchema,
      description: "Taxa commonly confused with this one",
    },
    ecology: {
      type: "string" as const,
      description: "Habitat, ecological role, and distribution (Markdown supported, use bolding for keywords)",
    },
    etymology: {
      type: "string" as const,
      description: "Origin of the scientific name (Markdown supported, use bolding for roots)",
    },
    history: {
      type: "string" as const,
      description: "Historical/pre-Linnaean context (Markdown supported, use bolding for key people/dates)",
    },
    distribution: {
      type: "string" as const,
      description: "Geographic range (Markdown supported, use bolding for countries/regions)",
    },
  },
  required: [
    "scientificName",
    "author",
    "commonName",
    "family",
    "quickRecap",
    "diagnosticDescription",
    "confusedTaxa",
    "ecology",
    "etymology",
    "history",
    "distribution",
  ],
};

// Helper to extract sources from grounding metadata
const extractSources = (response: any): Source[] => {
  const sources: Source[] = [];
  const candidates = response.candidates;
  if (candidates && candidates.length > 0) {
    const candidate = candidates[0];
    const groundingMetadata = candidate.groundingMetadata;
    if (groundingMetadata && groundingMetadata.groundingChunks) {
      groundingMetadata.groundingChunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({
            title: chunk.web.title || "Source",
            uri: chunk.web.uri,
          });
        }
      });
    }
  }
  // Deduplicate sources by URI
  return Array.from(new Map(sources.map((s) => [s.uri, s])).values());
};

const handleApiError = (error: any) => {
  console.error("Gemini API Error:", error);
  const msg = error.message || "";
  const name = error.name || "";

  // Specific handling for AbortError which often happens in Firefox with AdBlockers or strict privacy settings on long requests
  if (
    name === "AbortError" ||
    msg.includes("aborted") ||
    msg.includes("Failed to fetch")
  ) {
    throw new Error(
      "Connection failed or was aborted. If you are using Firefox, this is a known issue caused by strict tracking protection or extensions—please try using Chrome or disabling ad-blockers for this site."
    );
  }
  throw error;
};

export const analyzeTaxon = async (taxonName: string): Promise<TaxonData> => {
  try {
    const ai = new GoogleGenAI({ apiKey: getApiKey() });

    const prompt = `Act as an expert Taxonomist and Field Biologist.
Analyze the taxon: "${taxonName}".

First, use Google Search to verify the latest taxonomic classifications and precise diagnostic morphological characters.

Provide a strictly factual, professional profile.
If the taxon name is ambiguous, select the most likely valid scientific species.

IMPORTANT INSTRUCTIONS FOR FORMATTING:
1. 'quickRecap' MUST include the primary diagnostic morphological characters (e.g. leaf arrangement, floral structure, unique habit).
2. 'diagnosticDescription' MUST be a structured Markdown list where each feature is a separate bullet point.
3. USE BOLDING (**keyword**) liberally for the most decisive morphological characters throughout ALL fields to highlight what makes this taxon unique.
4. For 'diagnosticDescription', ensure each item follows this style: "- **Feature**: Detailed description with **decisive traits** in bold."`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 16000 },
        responseSchema: taxonSchema,
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text) as TaxonData;

    // Cleanup redundant introductory text if present (defensive)
    if (data.diagnosticDescription) {
      data.diagnosticDescription = data.diagnosticDescription.replace(
        /^(A )?detailed guide to identification[:.]?\s*/i,
        ""
      );
    }

    data.sources = extractSources(response);

    return data;
  } catch (error) {
    handleApiError(error);
    throw error; // TS fallback
  }
};

export const compareTaxa = async (names: string[]): Promise<ComparisonData> => {
  try {
    const ai = new GoogleGenAI({ apiKey: getApiKey() });
    const count = names.length;

    // Dynamically build the schema based on input count
    const taxonProperties: any = {};
    const differenceProperties: any = {};

    names.forEach((_, index) => {
      const key = `taxon${index + 1}`;
      taxonProperties[key] = taxonSchema;
      differenceProperties[`taxon${index + 1}State`] = {
        type: "string" as const,
        description: `State in taxon ${index + 1} (Markdown supported, use bolding for diagnostic states)`,
      };
    });

    const comparisonSchema = {
      type: "object" as const,
      properties: {
        ...taxonProperties,
        keyDifferences: {
          type: "array" as const,
          items: {
            type: "object" as const,
            properties: {
              feature: {
                type: "string" as const,
                description: "The morphological character being compared",
              },
              ...differenceProperties,
            },
            required: ["feature", ...Object.keys(differenceProperties)],
          },
          description: "Key diagnostic differences between the taxa",
        },
      },
      required: [
        ...Object.keys(taxonProperties),
        "keyDifferences",
      ],
    };

    const prompt = `Act as an expert Taxonomist.
Compare the following ${count} taxa: ${names.map((n) => `"${n}"`).join(", ")}.

Use Google Search to verify recent taxonomic literature and precise differences.

Provide full profiles for all taxa. The 'keyDifferences' array must focus on the most diagnostic characters that distinguish them in the field.

IMPORTANT: 
- 'quickRecap' for each taxon must include its primary morphological identifier.
- Liberally use BOLDING (**keyword**) for the most decisive characters that distinguish these species in every field.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 16000 },
        responseSchema: comparisonSchema,
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const rawData = JSON.parse(text);

    const taxa: TaxonData[] = [];
    for (let i = 0; i < count; i++) {
      const key = `taxon${i + 1}`;
      if (rawData[key]) {
        if (rawData[key].diagnosticDescription) {
          rawData[key].diagnosticDescription =
            rawData[key].diagnosticDescription.replace(
              /^(A )?detailed guide to identification[:.]?\s*/i,
              ""
            );
        }
        taxa.push(rawData[key]);
      }
    }

    const keyDifferences = (rawData.keyDifferences || []).map((diff: any) => ({
      feature: diff.feature,
      states: names.map((_, i) => diff[`taxon${i + 1}State`] || "N/A"),
    }));

    return {
      taxa,
      keyDifferences,
      sources: extractSources(response),
    };
  } catch (error) {
    handleApiError(error);
    throw error;
  }
};

