/**
 * Component to safely render Markdown content using 'marked'
 */
const MarkdownRenderer: React.FC<{ content: string; className?: string }> = ({ content, className = '' }) => {
  if (!content) return null;

  // Parse markdown to HTML
  const html = parse(content) as string;

  return (
    <div 
      className={`prose-custom text-slate-300 ${className}`} 
      dangerouslySetInnerHTML={{ __html: html }} 
    />
  );
};

/**
 * Skeleton Loader for smooth loading states
 */
const SkeletonCard: React.FC<{ className?: string }> = ({ className = '' }) => (
  <div className={`rounded-xl border border-slate-800/50 bg-slate-900/50 p-6 ${className}`}>
    <div className="flex items-center gap-3 mb-4">
      <div className="w-10 h-10 rounded-lg bg-slate-800 animate-pulse"></div>
      <div className="h-6 w-1/3 bg-slate-800 rounded animate-pulse"></div>
    </div>
    <div className="space-y-3">
      <div className="h-4 w-full bg-slate-800/50 rounded animate-pulse"></div>
      <div className="h-4 w-5/6 bg-slate-800/50 rounded animate-pulse"></div>
      <div className="h-4 w-4/6 bg-slate-800/50 rounded animate-pulse"></div>
    </div>
  </div>
);

const SourceList: React.FC<{ sources?: Source[] }> = ({ sources }) => {
  if (!sources || sources.length === 0) return null;

  return (
    <div className="mt-10 pt-8 border-t border-slate-800/50">
      <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
        <div className="w-1 h-4 bg-cyan-500/50 rounded-full"></div>
        Verified Sources
      </h4>
      <div className="flex flex-wrap gap-2">
        {sources.map((source, idx) => (
          <a 
            key={idx} 
            href={source.uri} 
            target="_blank" 
            rel="noopener noreferrer"
            className="group text-xs text-cyan-500 hover:text-cyan-400 bg-slate-900/50 px-4 py-2 rounded-lg border border-slate-800/50 hover:border-cyan-800/50 hover:bg-slate-800/50 transition-all duration-200 truncate max-w-[220px] hover:shadow-lg hover:shadow-cyan-900/10"
            title={source.title}
          >
            <span className="flex items-center gap-2">
              <svg className="w-3 h-3 opacity-50 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
              {source.title || new URL(source.uri).hostname}
            </span>
          </a>
        ))}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>(Mode.SINGLE);
  const [inputs, setInputs] = useState<string[]>(['']);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [singleData, setSingleData] = useState<TaxonData | null>(null);
  const [compareData, setCompareData] = useState<ComparisonData | null>(null);

  const resultsRef = useRef<HTMLDivElement>(null);

  const handleSearch = async () => {
    const validInputs = inputs.map(i => i.trim()).filter(i => i.length > 0);

    if (validInputs.length === 0) return;
    if (mode === Mode.COMPARE && validInputs.length < 2) {
      setError("Please enter at least two taxa to compare.");
      return;
    }

    setLoading(true);
    setError(null);
    setSingleData(null);
    setCompareData(null);

    try {
      if (mode === Mode.SINGLE) {
        const data = await analyzeTaxon(validInputs[0]);
        setSingleData(data);
      } else {
        const data = await compareTaxa(validInputs);
        setCompareData(data);
      }
      setTimeout(() => {
        resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred while fetching taxon data.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  const loadExample = (ex: string) => {
    setInputs([ex]);
    setMode(Mode.SINGLE);
    setSingleData(null);
    setCompareData(null);
  };

  const updateInput = (index: number, value: string) => {
    const newInputs = [...inputs];
    newInputs[index] = value;
    setInputs(newInputs);
  };

  const addInput = () => {
    if (inputs.length < 3) {
      setInputs([...inputs, '']);
    }
  };

  const removeInput = (index: number) => {
    if (inputs.length > 2) {
      const newInputs = inputs.filter((_, i) => i !== index);
      setInputs(newInputs);
    }
  };

  const toggleMode = () => {
    if (mode === Mode.SINGLE) {
      setMode(Mode.COMPARE);
      if (inputs.length < 2) {
        setInputs([inputs[0] || '', '']);
      }
    } else {
      setMode(Mode.SINGLE);
      setInputs([inputs[0] || '']);
    }
    setSingleData(null);
    setCompareData(null);
  };

  const handlePrint = () => {
    const content = resultsRef.current;
    if (!content) return;

    // Use a new window to bypass iframe print restrictions and control the print layout strictly
    const printWindow = window.open('', '_blank', 'height=800,width=900');

    if (!printWindow) {
      alert("Please allow pop-ups for this site to enable the print view.");
      return;
    }

    // Collect styles to maintain formatting
    const styles = Array.from(document.querySelectorAll('style, link[rel="stylesheet"]'))
      .map(style => style.outerHTML)
      .join('');

    // Collect tailwind script
    const scripts = Array.from(document.querySelectorAll('script[src*="tailwindcss"]'))
      .map(script => script.outerHTML)
      .join('');

    const html = `
      <!DOCTYPE html>
      <html lang="en">
        <head>
          <meta charset="UTF-8">
          <title>Taxon Profile - Print View</title>
          ${styles}
          ${scripts}
          <link rel="preconnect" href="https://fonts.googleapis.com">
          <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
          <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Merriweather:ital,wght@0,300;0,400;0,700;1,400&display=swap" rel="stylesheet">
          <style>
            body { 
              background-color: white !important; 
              color: black !important; 
              font-family: 'Inter', sans-serif;
              padding: 40px;
            }
            .print-container {
              max-width: 900px;
              margin: 0 auto;
            }
            /* Force colors for print readability */
            * {
              text-shadow: none !important;
              box-shadow: none !important;
              color: black !important;
              border-color: #ccc !important;
            }
            .bg-slate-900, .bg-slate-950, .bg-slate-800 {
              background-color: white !important;
              border: 1px solid #ddd !important;
            }
            a { text-decoration: underline !important; color: #000 !important; }
            h1, h2, h3 { color: #000 !important; page-break-after: avoid; }
            img, svg { filter: grayscale(100%); }
            .no-print { display: none !important; }
          </style>
        </head>
        <body>
          <div class="print-container">
            <h1 style="font-family: Merriweather, serif; font-size: 24px; margin-bottom: 20px; border-bottom: 2px solid black; padding-bottom: 10px;">
              Taxon Profile Report
            </h1>
            ${content.innerHTML}
            <div style="margin-top: 40px; font-size: 10px; border-top: 1px solid #ccc; padding-top: 10px; text-align: center;">
              Generated by Taxon Profiles AI • ${new Date().toLocaleDateString()}
            </div>
          </div>
          <script>
            window.onload = () => {
              setTimeout(() => {
                window.print();
              }, 800);
            };
          </script>
        </body>
      </html>
    `;

    printWindow.document.write(html);
    printWindow.document.close();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 text-slate-200 selection:bg-cyan-500/30 pb-20 print:bg-white print:text-black print:pb-0">

      {/* Subtle background pattern - Hidden on print */}
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-cyan-900/5 via-transparent to-transparent pointer-events-none print:hidden"></div>

      {/* Header / Hero */}
      <header className="relative pt-24 pb-16 px-4 text-center max-w-5xl mx-auto print:pt-4 print:pb-8">
        <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/5 to-transparent blur-3xl -z-10 print:hidden"></div>

        <h1 className="text-6xl md:text-7xl font-bold text-white mb-6 tracking-tight print:text-black print:text-4xl print:mb-2">
          Taxon <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-teal-400 to-emerald-400 animate-gradient print:text-black print:bg-none">Profiles</span>
