            <div className="text-center mb-8"><div className="h-12 w-64 bg-slate-800/50 rounded-lg mx-auto mb-4 animate-pulse"></div><div className="h-4 w-32 bg-slate-800/50 rounded-lg mx-auto animate-pulse"></div></div>
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6"><div className="lg:col-span-8"><SkeletonCard className="h-64" /></div><div className="lg:col-span-4 space-y-6"><SkeletonCard className="h-40" /><SkeletonCard className="h-40" /></div></div>
          </div>
        )}

        {singleData && !loading && (
          <div className="space-y-8 animate-in fade-in duration-500 max-w-6xl mx-auto">
            <div className="text-center mb-12 relative group print:mb-6">
               <h2 className="text-5xl md:text-6xl font-bold text-white mb-3 tracking-tight print:text-black print:text-3xl flex items-baseline justify-center gap-4 flex-wrap relative">
                 <i className="italic font-serif cursor-help" onClick={() => copyToClipboard(singleData.scientificName)} title="Click to copy">{singleData.scientificName}</i>
                 {singleData.author && <span className="text-xl md:text-2xl text-slate-400 font-normal not-italic print:text-black">{singleData.author}</span>}
               </h2>
               <p className="text-2xl text-cyan-400 font-medium mb-4 print:text-black">{singleData.commonName}</p>
               <span className="inline-block px-4 py-2 bg-slate-900/50 text-slate-400 text-xs uppercase tracking-widest rounded-xl border border-slate-800/50 print:bg-white print:text-black">{singleData.family}</span>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
              <div className="lg:col-span-12"><TaxonCard title="Quick Recap" icon={<StarIcon className="w-5 h-5" />} highlight><MarkdownRenderer content={singleData.quickRecap} /></TaxonCard></div>
              <div className="lg:col-span-8"><TaxonCard title="Diagnostic Features" icon={<HandLensIcon className="w-5 h-5" />}><MarkdownRenderer content={singleData.diagnosticDescription} /></TaxonCard></div>
              <div className="lg:col-span-4 space-y-6">
                 <TaxonCard title="Ecology & Range" icon={<GlobeIcon className="w-5 h-5" />}>
                    <div className="mb-5"><strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70 print:text-black">Habitat</strong><MarkdownRenderer content={singleData.ecology} /></div>
                    <div><strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70 print:text-black">Distribution</strong><MarkdownRenderer content={singleData.distribution} /></div>
                 </TaxonCard>
                 <TaxonCard title="Etymology" icon={<BookOpenIcon className="w-5 h-5" />}><div className="text-slate-400 text-sm"><MarkdownRenderer content={singleData.etymology} /></div></TaxonCard>
                 <TaxonCard title="History" icon={<ScrollIcon className="w-5 h-5" />}><div className="text-slate-400 text-sm"><MarkdownRenderer content={singleData.history} /></div></TaxonCard>
              </div>
              <div className="lg:col-span-12">
                 <TaxonCard title="Similar Species" icon={<AlertTriangleIcon className="w-5 h-5" />} className="border-orange-900/20">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                       {singleData.confusedTaxa.map((taxon, idx) => (
                         <div key={idx} className="bg-slate-950/30 p-5 rounded-xl border border-slate-800/50 group hover:border-orange-900/40 transition-all print:bg-white">
                            <h4 className="font-bold text-orange-300 mb-3 italic text-lg print:text-black">{taxon.name}</h4>
                            <div className="text-sm text-slate-400 mb-3"><MarkdownRenderer content={taxon.difference} /></div>
                            <div className="pt-3 border-t border-slate-800/50"><span className="text-xs text-orange-400/70 uppercase tracking-wide font-semibold">Key Feature: </span><span className="text-xs text-orange-300 print:text-black">{taxon.keyFeature}</span></div>
                         </div>
                       ))}
                    </div>
                 </TaxonCard>
              </div>
              {singleData.sources && <div className="lg:col-span-12"><SourceList sources={singleData.sources} /></div>}
            </div>
          </div>
        )}

        {compareData && !loading && (
          <div className="animate-in fade-in duration-500">
             <div className={`grid gap-6 mb-10 text-center ${compareData.taxa.length === 3 ? 'grid-cols-1 md:grid-cols-3' : 'grid-cols-1 md:grid-cols-2'}`}>
                {compareData.taxa.map((taxon, idx) => (
                  <div key={idx} className="relative p-8 bg-slate-900/40 backdrop-blur-sm rounded-3xl border border-slate-800/50 flex flex-col justify-center h-full print:bg-white">
                     <h2 className="text-3xl font-bold text-white mb-2 print:text-black"><i className="italic font-serif">{taxon.scientificName}</i></h2>
                     <p className="text-xl text-cyan-400 font-medium print:text-black">{taxon.commonName}</p>
                  </div>
                ))}
             </div>

             <div className="mb-10">
                <div className="bg-slate-900/40 backdrop-blur-sm border border-slate-800/50 rounded-3xl overflow-hidden shadow-2xl print:bg-white">
                   <div className="bg-gradient-to-r from-slate-900 to-slate-800/50 p-6 text-center border-b border-slate-800/50 print:bg-white">
                      <h3 className="text-xl font-bold text-white flex items-center justify-center gap-3 print:text-black">Key Diagnostic Characters</h3>
                   </div>
                   <div className="overflow-x-auto comparison-table">
                     <table className="w-full text-left text-slate-300 text-sm min-w-[600px] print:text-black">
                        <thead className="bg-slate-950/80 text-slate-400 text-xs uppercase tracking-wider print:bg-gray-100">
                           <tr>
                              <th className="p-5 font-semibold w-1/4 sticky-col">Character</th>
                              {compareData.taxa.map((taxon, idx) => (
                                <th key={idx} className="p-5 font-semibold italic border-l border-slate-800/20">{taxon.scientificName}</th>
                              ))}
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800/30">
                           {compareData.keyDifferences.map((diff, idx) => (
                              <tr key={idx} className="hover:bg-slate-800/20 transition-colors">
                                 <td className="p-5 font-medium text-cyan-300 sticky-col border-r border-slate-800/20">{diff.feature}</td>
                                 {diff.states.map((state, sIdx) => (
                                   <td key={sIdx} className="p-5 border-l border-slate-800/20 align-top"><MarkdownRenderer content={state} /></td>
                                 ))}
                              </tr>
                           ))}
                        </tbody>
                     </table>
                   </div>
                </div>
             </div>

             <div className={`grid gap-6 items-start ${compareData.taxa.length === 3 ? 'lg:grid-cols-3' : 'lg:grid-cols-2'}`}>
                <div className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                   <h3 className="text-2xl font-bold text-white mb-6 border-b border-slate-800/50 pb-4 print:text-black">Detailed Side-by-Side Profiles</h3>
                </div>
                {['Overview', 'Ecology', 'Etymology', 'Historical Context'].map((section) => (
                   <TaxonCard key={section} title={section} icon={<HandLensIcon className="w-5 h-5"/>} className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                      <div className={`grid gap-6 ${compareData.taxa.length === 3 ? 'lg:grid-cols-3' : 'lg:grid-cols-2'}`}>
                         {compareData.taxa.map((taxon, idx) => (
                           <div key={idx} className="border-l-2 border-slate-800/50 pl-5 print:border-gray-300">
                             <h4 className="font-bold text-white mb-3 italic text-lg print:text-black">{taxon.scientificName}</h4>
                             <MarkdownRenderer content={
                               section === 'Overview' ? taxon.quickRecap : 
                               section === 'Ecology' ? taxon.ecology : 
                               section === 'Etymology' ? taxon.etymology : taxon.history
                             } />
                           </div>
                         ))}
                      </div>
                   </TaxonCard>
                ))}
             </div>
             {compareData.sources && <SourceList sources={compareData.sources} />}
          </div>
        )}
      </main>

      <footer className="relative mt-24 max-w-6xl mx-auto px-4 text-center py-10 border-t border-slate-800/30 print:hidden">
        <p className="text-slate-500 text-sm mb-3">Powered by Gemini 3 Flash with Search Grounding</p>
        <p className="text-slate-600 text-xs">AI-generated content. For critical research, verify with botanical or zoological literature.</p>
      </footer>

      {showBackToTop && (
        <button 
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className="fixed bottom-8 right-8 p-4 bg-cyan-600/80 backdrop-blur text-white rounded-full shadow-2xl hover:bg-cyan-500 transition-all z-50 print:hidden"
          title="Back to Top"
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
        </button>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { parse } from 'marked';
import { analyzeTaxon, compareTaxa } from './services/geminiService';
import { TaxonData, ComparisonData, Mode, Source } from './types';
import { 
  SearchIcon, StarIcon, HandLensIcon, GlobeIcon, 
  BookOpenIcon, ScrollIcon, AlertTriangleIcon, ArrowRightLeftIcon, XIcon, PrinterIcon 
} from './components/Icons';
import { TaxonCard } from './components/TaxonCard';

// Placeholder examples
const EXAMPLES = ['Amanita muscaria', 'Quercus robur', 'Canis lupus', 'Monarch Butterfly', 'Eupatorieae'];

// Cache Key Prefix
const CACHE_PREFIX = 'taxon_cache_v1_';

/**
 * Component to safely render Markdown content using 'marked'
 */
const MarkdownRenderer: React.FC<{ content: string; className?: string }> = ({ content, className = '' }) => {
  if (!content) return null;
  const html = parse(content) as string;
  return (
    <div 
      className={`prose-custom text-slate-300 ${className}`} 
      dangerouslySetInnerHTML={{ __html: html }} 
    />
  );
};

const SkeletonCard: React.FC<{ className?: string }> = ({ className = '' }) => (
  <div className={`rounded-xl border border-slate-800/50 bg-slate-900/50 p-6 ${className}`}>
    <div className="flex items-center gap-3 mb-4">
      <div className="w-10 h-10 rounded-lg bg-slate-800 animate-pulse"></div>
      <div className="h-6 w-1/3 bg-slate-800 rounded animate-pulse"></div>
    </div>
    <div className="space-y-3">
      <div className="h-4 w-full bg-slate-800/50 rounded animate-pulse"></div>
      <div className="h-4 w-5/6 bg-slate-800/50 rounded animate-pulse"></div>
      <div className="h-4 w-4/6 bg-slate-800/50 rounded animate-pulse"></div>
    </div>
  </div>
);

const SourceList: React.FC<{ sources?: Source[] }> = ({ sources }) => {
  if (!sources || sources.length === 0) return null;
  return (
    <div className="mt-10 pt-8 border-t border-slate-800/50">
      <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
        <div className="w-1 h-4 bg-cyan-500/50 rounded-full"></div>
        Verified Sources
      </h4>
      <div className="flex flex-wrap gap-2">
        {sources.map((source, idx) => (
          <a 
            key={idx} 
            href={source.uri} 
            target="_blank" 
            rel="noopener noreferrer"
            className="group text-xs text-cyan-500 hover:text-cyan-400 bg-slate-900/50 px-4 py-2 rounded-lg border border-slate-800/50 hover:border-cyan-800/50 hover:bg-slate-800/50 transition-all duration-200 truncate max-w-[220px] hover:shadow-lg hover:shadow-cyan-900/10"
            title={source.title}
          >
            <span className="flex items-center gap-2">
              <svg className="w-3 h-3 opacity-50 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
              {source.title || new URL(source.uri).hostname}
            </span>
          </a>
        ))}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>(Mode.SINGLE);
  const [inputs, setInputs] = useState<string[]>(['']);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [singleData, setSingleData] = useState<TaxonData | null>(null);
  const [compareData, setCompareData] = useState<ComparisonData | null>(null);
  const [showBackToTop, setShowBackToTop] = useState(false);

  const resultsRef = useRef<HTMLDivElement>(null);
  const firstInputRef = useRef<HTMLInputElement>(null);

  // Focus input on mount
  useEffect(() => {
    firstInputRef.current?.focus();

    const handleScroll = () => {
      setShowBackToTop(window.scrollY > 500);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const getCachedData = (key: string) => {
    const cached = localStorage.getItem(CACHE_PREFIX + key.toLowerCase().trim());
    return cached ? JSON.parse(cached) : null;
  };

  const setCacheData = (key: string, data: any) => {
    try {
      localStorage.setItem(CACHE_PREFIX + key.toLowerCase().trim(), JSON.stringify(data));
    } catch (e) {
      console.warn("Storage quota exceeded, cache skipped.");
    }
  };

  const handleSearch = async () => {
    const validInputs = inputs.map(i => i.trim()).filter(i => i.length > 0);
    if (validInputs.length === 0) return;
    if (mode === Mode.COMPARE && validInputs.length < 2) {
      setError("Please enter at least two taxa to compare.");
      return;
    }

    const cacheKey = mode + '_' + validInputs.sort().join('|');
    const cached = getCachedData(cacheKey);

    if (cached) {
      setError(null);
      if (mode === Mode.SINGLE) setSingleData(cached);
      else setCompareData(cached);
      setTimeout(() => resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
      return;
    }

    setLoading(true);
    setError(null);
    setSingleData(null);
    setCompareData(null);

    try {
      if (mode === Mode.SINGLE) {
        const data = await analyzeTaxon(validInputs[0]);
        setSingleData(data);
        setCacheData(cacheKey, data);
      } else {
        const data = await compareTaxa(validInputs);
        setCompareData(data);
        setCacheData(cacheKey, data);
      }
      setTimeout(() => resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred while fetching taxon data.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  const loadExample = (ex: string) => {
    setInputs([ex]);
    setMode(Mode.SINGLE);
    handleSearch(); // Automatically trigger search for UX
  };

  const updateInput = (index: number, value: string) => {
    const newInputs = [...inputs];
    newInputs[index] = value;
    setInputs(newInputs);
    if (error) setError(null);
  };

  const addInput = () => {
    if (inputs.length < 3) {
      setInputs([...inputs, '']);
    }
  };

  const removeInput = (index: number) => {
    if (inputs.length > 2) {
      const newInputs = inputs.filter((_, i) => i !== index);
      setInputs(newInputs);
    }
  };

  const toggleMode = () => {
    if (mode === Mode.SINGLE) {
      setMode(Mode.COMPARE);
      if (inputs.length < 2) setInputs([inputs[0] || '', '']);
    } else {
      setMode(Mode.SINGLE);
      setInputs([inputs[0] || '']);
    }
    setSingleData(null);
    setCompareData(null);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    // Could add a toast here
  };

  const handlePrint = () => {
    const content = resultsRef.current;
    if (!content) return;
    const printWindow = window.open('', '_blank', 'height=800,width=900');
    if (!printWindow) {
      alert("Please allow pop-ups for this site to enable the print view.");
      return;
    }
    const styles = Array.from(document.querySelectorAll('style, link[rel="stylesheet"]'))
      .map(style => style.outerHTML)
      .join('');
    const scripts = Array.from(document.querySelectorAll('script[src*="tailwindcss"]'))
      .map(script => script.outerHTML)
      .join('');
    const html = `
      <!DOCTYPE html>
      <html lang="en">
        <head>
          <meta charset="UTF-8">
          <title>Taxon Profile Report</title>
          ${styles}
          ${scripts}
          <link rel="preconnect" href="https://fonts.googleapis.com">
          <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
          <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Merriweather:ital,wght@0,300;0,400;0,700;1,400&display=swap" rel="stylesheet">
          <style>
            body { background: white !important; color: black !important; padding: 40px; font-family: 'Inter', sans-serif; }
            .bg-slate-900, .bg-slate-950, .bg-slate-800 { background: white !important; border: 1px solid #eee !important; color: black !important; }
            * { color: black !important; border-color: #ddd !important; }
            .no-print, .copy-btn { display: none !important; }
          </style>
        </head>
        <body>
          <h1 style="font-family: Merriweather, serif; font-size: 24px; border-bottom: 2px solid #000; padding-bottom: 10px; margin-bottom: 20px;">Taxon Profile Report</h1>
          ${content.innerHTML}
          <div style="margin-top: 40px; font-size: 10px; text-align: center; border-top: 1px solid #eee; padding-top: 10px;">Generated on ${new Date().toLocaleString()}</div>
          <script>window.onload = () => setTimeout(() => window.print(), 500);</script>
        </body>
      </html>
    `;
    printWindow.document.write(html);
    printWindow.document.close();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 text-slate-200 selection:bg-cyan-500/30 pb-20 print:bg-white print:text-black">
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-cyan-900/5 via-transparent to-transparent pointer-events-none print:hidden"></div>

      <header className="relative pt-24 pb-16 px-4 text-center max-w-5xl mx-auto print:pt-4">
        <h1 className="text-6xl md:text-7xl font-bold text-white mb-6 tracking-tight print:text-black print:text-4xl">
          Taxon <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-teal-400 to-emerald-400">Profiles</span>
        </h1>
        <p className="text-lg md:text-xl text-slate-400 mb-12 max-w-3xl mx-auto leading-relaxed font-light print:text-black print:text-sm">
          A biological identification assistant focusing on diagnostic morphological characters and providing other essential information.
        </p>

        <div className="relative bg-slate-900/40 backdrop-blur-xl border border-slate-800/50 p-3 rounded-3xl shadow-2xl max-w-3xl mx-auto print:hidden">
          <div className="flex flex-col gap-3 p-3">
            {inputs.map((input, index) => (
              <div key={index} className="relative flex items-center gap-3 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="relative flex-grow group">
                  <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-500 w-5 h-5 transition-colors" />
                  <input
                    ref={index === 0 ? firstInputRef : null}
                    type="text"
                    value={input}
                    onChange={(e) => updateInput(index, e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={mode === Mode.COMPARE ? `Taxon ${index + 1}` : "Enter name (e.g., Amanita muscaria)..."}
                    className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl py-4 pl-12 pr-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-cyan-500/30 transition-all"
                  />
                </div>
                {mode === Mode.COMPARE && index > 1 && (
                  <button onClick={() => removeInput(index)} className="p-4 bg-slate-950/50 hover:bg-red-950/20 text-slate-500 hover:text-red-400 rounded-2xl border border-slate-800/50 transition-all"><XIcon className="w-5 h-5" /></button>
                )}
              </div>
            ))}

            {mode === Mode.COMPARE && inputs.length < 3 && (
              <button onClick={addInput} className="py-3 px-4 rounded-2xl border border-dashed border-slate-800/50 text-slate-500 hover:text-cyan-400 hover:border-cyan-800/50 transition-all text-sm font-medium">+ Add Taxon</button>
            )}

            <button
              onClick={handleSearch}
              disabled={loading}
              className="relative mt-3 bg-gradient-to-r from-cyan-600 to-teal-600 hover:from-cyan-500 hover:to-emerald-600 text-white font-semibold py-4 px-8 rounded-2xl transition-all shadow-lg disabled:opacity-50 w-full group overflow-hidden"
            >
              {loading ? <span className="flex items-center justify-center gap-2"><span className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full"></span>Analyzing</span> : (mode === Mode.COMPARE ? 'Compare Taxa' : 'Analyze Taxon')}
            </button>
          </div>

          <div className="flex justify-between items-center py-3 border-t border-slate-800/30 mt-2 px-2">
             <button onClick={toggleMode} className="flex items-center gap-2 text-sm font-medium text-cyan-400 hover:text-cyan-300 transition-colors">
                {mode === Mode.SINGLE ? <><ArrowRightLeftIcon className="w-4 h-4" /> Comparison Mode</> : <><XIcon className="w-4 h-4" /> Cancel Comparison</>}
             </button>
             {(singleData || compareData) && (
               <button onClick={handlePrint} className="flex items-center gap-2 text-sm font-medium text-slate-400 hover:text-white transition-colors"><PrinterIcon className="w-4 h-4" /> Print / PDF</button>
             )}
          </div>
        </div>

        {!singleData && !compareData && !loading && (
          <div className="mt-10 flex flex-wrap justify-center gap-3 animate-in fade-in slide-in-from-bottom-4 duration-700 print:hidden">
            <span className="text-xs text-slate-500 uppercase tracking-widest mr-2 self-center">Quick Examples:</span>
            {EXAMPLES.map(ex => (
              <button key={ex} onClick={() => loadExample(ex)} className="px-5 py-2 bg-slate-900/30 hover:bg-slate-800/50 border border-slate-800/30 rounded-full text-sm text-slate-400 hover:text-slate-200 transition-all">{ex}</button>
            ))}
          </div>
        )}
      </header>

      <main ref={resultsRef} className="relative max-w-7xl mx-auto px-4 print:px-0">
        {error && <div className="p-6 bg-red-950/30 border border-red-500/30 rounded-2xl text-red-200 text-center mb-12 max-w-4xl mx-auto"><AlertTriangleIcon className="w-8 h-8 mx-auto mb-3 text-red-400" /><p>{error}</p></div>}

        {loading && (
          <div className="max-w-6xl mx-auto space-y-6">
            <div className="text-center mb-8"><div className="h-12 w-64 bg-slate-800/50 rounded-lg mx-auto mb-4 animate-pulse"></div><div className="h-4 w-32 bg-slate-800/50 rounded-lg mx-auto animate-pulse"></div></div>
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6"><div className="lg:col-span-8"><SkeletonCard className="h-64" /></div><div className="lg:col-span-4 space-y-6"><SkeletonCard className="h-40" /><SkeletonCard className="h-40" /></div></div>
          </div>
        )}

        {singleData && !loading && (
          <div className="space-y-8 animate-in fade-in duration-500 max-w-6xl mx-auto">
            <div className="text-center mb-12 relative group print:mb-6">
               <h2 className="text-5xl md:text-6xl font-bold text-white mb-3 tracking-tight print:text-black print:text-3xl flex items-baseline justify-center gap-4 flex-wrap relative">
                 <i className="italic font-serif cursor-help" onClick={() => copyToClipboard(singleData.scientificName)} title="Click to copy">{singleData.scientificName}</i>
                 {singleData.author && <span className="text-xl md:text-2xl text-slate-400 font-normal not-italic print:text-black">{singleData.author}</span>}
               </h2>
               <p className="text-2xl text-cyan-400 font-medium mb-4 print:text-black">{singleData.commonName}</p>
               <span className="inline-block px-4 py-2 bg-slate-900/50 text-slate-400 text-xs uppercase tracking-widest rounded-xl border border-slate-800/50 print:bg-white print:text-black">{singleData.family}</span>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
              <div className="lg:col-span-12"><TaxonCard title="Quick Recap" icon={<StarIcon className="w-5 h-5" />} highlight><MarkdownRenderer content={singleData.quickRecap} /></TaxonCard></div>
              <div className="lg:col-span-8"><TaxonCard title="Diagnostic Features" icon={<HandLensIcon className="w-5 h-5" />}><MarkdownRenderer content={singleData.diagnosticDescription} /></TaxonCard></div>
              <div className="lg:col-span-4 space-y-6">
                 <TaxonCard title="Ecology & Range" icon={<GlobeIcon className="w-5 h-5" />}>
                    <div className="mb-5"><strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70 print:text-black">Habitat</strong><MarkdownRenderer content={singleData.ecology} /></div>
                    <div><strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70 print:text-black">Distribution</strong><MarkdownRenderer content={singleData.distribution} /></div>
                 </TaxonCard>
                 <TaxonCard title="Etymology" icon={<BookOpenIcon className="w-5 h-5" />}><div className="text-slate-400 text-sm"><MarkdownRenderer content={singleData.etymology} /></div></TaxonCard>
                 <TaxonCard title="History" icon={<ScrollIcon className="w-5 h-5" />}><div className="text-slate-400 text-sm"><MarkdownRenderer content={singleData.history} /></div></TaxonCard>
              </div>
              <div className="lg:col-span-12">
                 <TaxonCard title="Similar Species" icon={<AlertTriangleIcon className="w-5 h-5" />} className="border-orange-900/20">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                       {singleData.confusedTaxa.map((taxon, idx) => (
                         <div key={idx} className="bg-slate-950/30 p-5 rounded-xl border border-slate-800/50 group hover:border-orange-900/40 transition-all print:bg-white">
                            <h4 className="font-bold text-orange-300 mb-3 italic text-lg print:text-black">{taxon.name}</h4>
                            <div className="text-sm text-slate-400 mb-3"><MarkdownRenderer content={taxon.difference} /></div>
                            <div className="pt-3 border-t border-slate-800/50"><span className="text-xs text-orange-400/70 uppercase tracking-wide font-semibold">Key Feature: </span><span className="text-xs text-orange-300 print:text-black">{taxon.keyFeature}</span></div>
                         </div>
                       ))}
                    </div>
                 </TaxonCard>
              </div>
              {singleData.sources && <div className="lg:col-span-12"><SourceList sources={singleData.sources} /></div>}
            </div>
          </div>
        )}

        {compareData && !loading && (
          <div className="animate-in fade-in duration-500">
             <div className={`grid gap-6 mb-10 text-center ${compareData.taxa.length === 3 ? 'grid-cols-1 md:grid-cols-3' : 'grid-cols-1 md:grid-cols-2'}`}>
                {compareData.taxa.map((taxon, idx) => (
                  <div key={idx} className="relative p-8 bg-slate-900/40 backdrop-blur-sm rounded-3xl border border-slate-800/50 flex flex-col justify-center h-full print:bg-white">
                     <h2 className="text-3xl font-bold text-white mb-2 print:text-black"><i className="italic font-serif">{taxon.scientificName}</i></h2>
                     <p className="text-xl text-cyan-400 font-medium print:text-black">{taxon.commonName}</p>
                  </div>
                ))}
             </div>

             <div className="mb-10">
                <div className="bg-slate-900/40 backdrop-blur-sm border border-slate-800/50 rounded-3xl overflow-hidden shadow-2xl print:bg-white">
                   <div className="bg-gradient-to-r from-slate-900 to-slate-800/50 p-6 text-center border-b border-slate-800/50 print:bg-white">
                      <h3 className="text-xl font-bold text-white flex items-center justify-center gap-3 print:text-black">Key Diagnostic Characters</h3>
                   </div>
                   <div className="overflow-x-auto comparison-table">
                     <table className="w-full text-left text-slate-300 text-sm min-w-[600px] print:text-black">
                        <thead className="bg-slate-950/80 text-slate-400 text-xs uppercase tracking-wider print:bg-gray-100">
                           <tr>
                              <th className="p-5 font-semibold w-1/4 sticky-col">Character</th>
                              {compareData.taxa.map((taxon, idx) => (
                                <th key={idx} className="p-5 font-semibold italic border-l border-slate-800/20">{taxon.scientificName}</th>
                              ))}
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800/30">
                           {compareData.keyDifferences.map((diff, idx) => (
                              <tr key={idx} className="hover:bg-slate-800/20 transition-colors">
                                 <td className="p-5 font-medium text-cyan-300 sticky-col border-r border-slate-800/20">{diff.feature}</td>
                                 {diff.states.map((state, sIdx) => (
                                   <td key={sIdx} className="p-5 border-l border-slate-800/20 align-top"><MarkdownRenderer content={state} /></td>
                                 ))}
                              </tr>
                           ))}
                        </tbody>
                     </table>
                   </div>
                </div>
             </div>

             <div className={`grid gap-6 items-start ${compareData.taxa.length === 3 ? 'lg:grid-cols-3' : 'lg:grid-cols-2'}`}>
                <div className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                   <h3 className="text-2xl font-bold text-white mb-6 border-b border-slate-800/50 pb-4 print:text-black">Detailed Side-by-Side Profiles</h3>
                </div>
                {['Overview', 'Ecology', 'Etymology', 'Historical Context'].map((section) => (
                   <TaxonCard key={section} title={section} icon={<HandLensIcon className="w-5 h-5"/>} className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                      <div className={`grid gap-6 ${compareData.taxa.length === 3 ? 'lg:grid-cols-3' : 'lg:grid-cols-2'}`}>
                         {compareData.taxa.map((taxon, idx) => (
                           <div key={idx} className="border-l-2 border-slate-800/50 pl-5 print:border-gray-300">
                             <h4 className="font-bold text-white mb-3 italic text-lg print:text-black">{taxon.scientificName}</h4>
                             <MarkdownRenderer content={
                               section === 'Overview' ? taxon.quickRecap : 
                               section === 'Ecology' ? taxon.ecology : 
                               section === 'Etymology' ? taxon.etymology : taxon.history
                             } />
                           </div>
                         ))}
                      </div>
                   </TaxonCard>
                ))}
             </div>
             {compareData.sources && <SourceList sources={compareData.sources} />}
          </div>
        )}
      </main>

      <footer className="relative mt-24 max-w-6xl mx-auto px-4 text-center py-10 border-t border-slate-800/30 print:hidden">
        <p className="text-slate-500 text-sm mb-3">Developed by Daniel Cahen - Powered by Gemini 3 Flash with Search Grounding</p>
        <p className="text-slate-600 text-xs">AI-generated content. For critical research, verify with botanical or zoological literature.</p>
      </footer>

      {showBackToTop && (
        <button 
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className="fixed bottom-8 right-8 p-4 bg-cyan-600/80 backdrop-blur text-white rounded-full shadow-2xl hover:bg-cyan-500 transition-all z-50 print:hidden"
          title="Back to Top"
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
        </button>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { parse } from 'marked';
import { analyzeTaxon, compareTaxa } from './services/geminiService';
import { TaxonData, ComparisonData, Mode, Source } from './types';
import { 
  SearchIcon, StarIcon, HandLensIcon, GlobeIcon, 
  BookOpenIcon, ScrollIcon, AlertTriangleIcon, ArrowRightLeftIcon, XIcon, PrinterIcon 
} from './components/Icons';
import { TaxonCard } from './components/TaxonCard';

// Placeholder examples
const EXAMPLES = ['Amanita muscaria', 'Quercus robur', 'Canis lupus', 'Monarch Butterfly', 'Eupatorieae'];

// Cache Key Prefix
const CACHE_PREFIX = 'taxon_cache_v1_';

const LOADING_STAGES = [
  "Consulting biological databases...",
  "Analyzing morphological literature...",
  "Synthesizing diagnostic features...",
  "Extracting verification sources...",
  "Finalizing taxon profile..."
];

/**
 * Component to safely render Markdown content using 'marked'
 */
const MarkdownRenderer: React.FC<{ content: string; className?: string }> = ({ content, className = '' }) => {
  if (!content) return null;
  const html = parse(content) as string;
  return (
    <div 
      className={`prose-custom text-slate-300 ${className}`} 
      dangerouslySetInnerHTML={{ __html: html }} 
    />
  );
};

const SkeletonCard: React.FC<{ className?: string }> = ({ className = '' }) => (
  <div className={`rounded-xl border border-slate-800/50 bg-slate-900/50 p-6 ${className}`}>
    <div className="flex items-center gap-3 mb-4">
      <div className="w-10 h-10 rounded-lg bg-slate-800 animate-pulse"></div>
      <div className="h-6 w-1/3 bg-slate-800 rounded animate-pulse"></div>
    </div>
    <div className="space-y-3">
      <div className="h-4 w-full bg-slate-800/50 rounded animate-pulse"></div>
      <div className="h-4 w-5/6 bg-slate-800/50 rounded animate-pulse"></div>
      <div className="h-4 w-4/6 bg-slate-800/50 rounded animate-pulse"></div>
    </div>
  </div>
);

const SourceList: React.FC<{ sources?: Source[]; sticky?: boolean }> = ({ sources, sticky = false }) => {
  if (!sources || sources.length === 0) return null;

  const content = (
    <div className={`${sticky ? 'flex items-center gap-4 py-2 px-4' : 'mt-10 pt-8 border-t border-slate-800/50'}`}>
      {!sticky && (
        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
          <div className="w-1 h-4 bg-cyan-500/50 rounded-full"></div>
          Verified Sources
        </h4>
      )}
      <div className="flex flex-wrap gap-2 overflow-x-auto no-scrollbar">
        {sources.map((source, idx) => (
          <a 
            key={idx} 
            href={source.uri} 
            target="_blank" 
            rel="noopener noreferrer"
            className={`group text-xs text-cyan-500 hover:text-cyan-400 bg-slate-900/50 px-3 py-1.5 rounded-lg border border-slate-800/50 hover:border-cyan-800/50 transition-all duration-200 truncate ${sticky ? 'max-w-[150px]' : 'max-w-[220px]'}`}
            title={source.title}
          >
            <span className="flex items-center gap-2">
              <span className="opacity-70 group-hover:opacity-100 transition-opacity">🔗</span>
              {source.title || new URL(source.uri).hostname}
            </span>
          </a>
        ))}
      </div>
    </div>
  );

  if (sticky) {
    return (
      <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-40 w-max max-w-[90vw] bg-slate-950/80 backdrop-blur-md border border-slate-800/50 rounded-2xl shadow-2xl print:hidden">
        {content}
      </div>
    );
  }

  return content;
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>(Mode.SINGLE);
  const [inputs, setInputs] = useState<string[]>(['']);
  const [loading, setLoading] = useState(false);
  const [loadingStage, setLoadingStage] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [singleData, setSingleData] = useState<TaxonData | null>(null);
  const [compareData, setCompareData] = useState<ComparisonData | null>(null);
  const [showBackToTop, setShowBackToTop] = useState(false);

  const resultsRef = useRef<HTMLDivElement>(null);
  const firstInputRef = useRef<HTMLInputElement>(null);

  // Focus input on mount & keyboard shortcut
  useEffect(() => {
    firstInputRef.current?.focus();

    const handleScroll = () => {
      setShowBackToTop(window.scrollY > 500);
    };

    const handleKeydown = (e: KeyboardEvent) => {
      if (e.key === '/' && document.activeElement?.tagName !== 'INPUT') {
        e.preventDefault();
        firstInputRef.current?.focus();
      }
    };

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('keydown', handleKeydown);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('keydown', handleKeydown);
    };
  }, []);

  // Cycle loading stages
  useEffect(() => {
    let interval: number;
    if (loading) {
      setLoadingStage(0);
      interval = window.setInterval(() => {
        setLoadingStage(prev => (prev + 1) % LOADING_STAGES.length);
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const getCachedData = (key: string) => {
    const cached = localStorage.getItem(CACHE_PREFIX + key.toLowerCase().trim());
    return cached ? JSON.parse(cached) : null;
  };

  const setCacheData = (key: string, data: any) => {
    try {
      localStorage.setItem(CACHE_PREFIX + key.toLowerCase().trim(), JSON.stringify(data));
    } catch (e) {
      console.warn("Storage quota exceeded, cache skipped.");
    }
  };

  const handleSearch = async () => {
    const validInputs = inputs.map(i => i.trim()).filter(i => i.length > 0);
    if (validInputs.length === 0) return;
    if (mode === Mode.COMPARE && validInputs.length < 2) {
      setError("Please enter at least two taxa to compare.");
      return;
    }

    const cacheKey = mode + '_' + validInputs.sort().join('|');
    const cached = getCachedData(cacheKey);

    if (cached) {
      setError(null);
      if (mode === Mode.SINGLE) setSingleData(cached);
      else setCompareData(cached);
      setTimeout(() => resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
      return;
    }

    setLoading(true);
    setError(null);
    setSingleData(null);
    setCompareData(null);

    try {
      if (mode === Mode.SINGLE) {
        const data = await analyzeTaxon(validInputs[0]);
        setSingleData(data);
        setCacheData(cacheKey, data);
      } else {
        const data = await compareTaxa(validInputs);
        setCompareData(data);
        setCacheData(cacheKey, data);
      }
      setTimeout(() => resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred. Try re-checking the spelling or use a genus-level name.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  const loadExample = (ex: string) => {
    setInputs([ex]);
    setMode(Mode.SINGLE);
    handleSearch();
  };

  const updateInput = (index: number, value: string) => {
    const newInputs = [...inputs];
    newInputs[index] = value;
    setInputs(newInputs);
    if (error) setError(null);
  };

  const addInput = () => {
    if (inputs.length < 3) {
      setInputs([...inputs, '']);
    }
  };

  const removeInput = (index: number) => {
    if (inputs.length > 1) {
      const newInputs = inputs.filter((_, i) => i !== index);
      setInputs(newInputs);
    }
  };

  const toggleMode = () => {
    if (mode === Mode.SINGLE) {
      setMode(Mode.COMPARE);
      if (inputs.length < 2) setInputs([inputs[0] || '', '']);
    } else {
      setMode(Mode.SINGLE);
      setInputs([inputs[0] || '']);
    }
    setSingleData(null);
    setCompareData(null);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const handlePrint = () => {
    const content = resultsRef.current;
    if (!content) return;
    const printWindow = window.open('', '_blank', 'height=800,width=900');
    if (!printWindow) {
      alert("Please allow pop-ups for this site to enable the print view.");
      return;
    }
    const styles = Array.from(document.querySelectorAll('style, link[rel="stylesheet"]'))
      .map(style => style.outerHTML)
      .join('');
    const scripts = Array.from(document.querySelectorAll('script[src*="tailwindcss"]'))
      .map(script => script.outerHTML)
      .join('');
    const html = `
      <!DOCTYPE html>
      <html lang="en">
        <head>
          <meta charset="UTF-8">
          <title>Taxon Profile Report</title>
          ${styles}
          ${scripts}
          <link rel="preconnect" href="https://fonts.googleapis.com">
          <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
          <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Merriweather:ital,wght@0,300;0,400;0,700;1,400&display=swap" rel="stylesheet">
          <style>
            body { background: white !important; color: black !important; padding: 40px; font-family: 'Inter', sans-serif; }
